// ContactShip asks for context right before an inbound call.
// Request body: { call: { direction, from_number, to_number }, agent_id,
// organization_id, contact: { id, full_name, email } or null for new callers }.
const request = $input.first().json.body ?? {};
const contact = request.contact ?? null;
const callerPhone = request.call?.from_number ?? '';

// Replace this with a lookup in your own system (CRM, database, Google Sheets...),
// for example by contact.id or callerPhone. Keep it fast: the call waits for it.
const context = {
  caller_name: contact?.full_name ?? '',
  caller_phone: callerPhone,
  is_known_customer: Boolean(contact?.id),
  // balance: 125,
  // order_status: 'ready for pickup',
};

// Return only what the agent needs, as a flat object (under 8,000 characters).
// Do not use the reserved keys contact_data, current_day_time or timezone.
return [{ json: context }];
